def repCount (a : ℕ → ℕ) (k : ℕ) (n : ℕ) : ℕ :=
  (Finset.Icc 1 k).sum fun j =>
    (Finset.Icc 0 j).filter (fun i => a i + a j ≤ n) |>.card. Key formulas: $R_k(n) = |\{(i,j) : 0 \leq i \leq j \leq k,\, j \geq 1,\, a_i + a_j \leq n\}|$

def IsGreedyNext (a : ℕ → ℕ) (k : ℕ) : Prop :=
  repCount a k (a (k + 1)) < a (k + 1) ∧
  ∀ m, a k < m → m < a (k + 1) → repCount a k m ≥ m
def IsRosenSequence (a : ℕ → ℕ) : Prop :=
  a 0 = 0 ∧ a 1 = 1 ∧ StrictMono a ∧ ∀ k ≥ 1, IsGreedyNext a k. Key formulas: $a_{k+1} = \min\{n > a_k : R_k(n) < n\}$
